use vstd::prelude::*;

// Removes all odd numbers from the input slice, preserving the order
// of the remaining (even) elements.
//
// Specification:
//   - The result contains exactly those elements `x` from `arr` for which
//     `x % 2 == 0`, in the same relative order.
//   - In particular, `result.len() <= arr.len()`, and every element of
//     `result` is even.
//
// We make use of `as_seq()` to convert the input slice and output Vec
// into specification‐level sequences (`Seq<i32>`), and then use the
// built‐in `filter` on sequences.
#[requires(true)]
#[ensures(
    // Every element in the returned Vec is even
    forall |i: usize| i < result.len() ==>
        result.as_seq()[i] % 2 == 0
)]
#[ensures(
    // Exactly the evens of `arr`, in the same order
    result.as_seq() ==
        arr.as_seq().filter(|&x: &i32| x % 2 == 0)
)]
pub fn remove_odd_numbers(arr: &[i32]) -> Vec<i32> {
    arr.iter()
       .copied()
       .filter(|x| x % 2 == 0)
       .collect()
}

